     1	import type { Cart } from "../cart.ts";
     2	import { CATALOGUE } from "../catalogue.ts";
     3	import { fail } from "../errors.ts";
     4	
     5	// Add qty of sku to the cart, merging with an existing line for the same sku.
     6	export function addItem(cart: Cart, sku: string, qty: number): Cart {
     7	  if (!(sku in CATALOGUE)) fail("E_UNKNOWN_SKU", `unknown sku ${sku}`);
     8	  const lines = cart.lines.map((l) => ({ ...l }));
     9	  const existing = lines.find((l) => l.sku === sku);
    10	  if (existing) existing.qty += qty;
    11	  else lines.push({ sku, qty });
    12	  return { lines };
    13	}
